('przypisać', 'to attribute, ascribe', 'приписывать', 'verb', NULL, 'C1', 1306, 'pʂɨpʲisat͡ɕ', 'Przypisuje to Platonowi.', 'He attributes it to Plato.', 'Он приписывает это Платону.'),
('metodologia', 'methodology', 'методология', 'noun', 'feminine', 'C1', 1307, 'mɛtɔdɔlɔgʲa', 'Metodologia badań.', 'Research methodology.', 'Методология исследований.'),
('empiryczny', 'empirical', 'эмпирический', 'adjective', 'masculine', 'C1', 1308, 'ɛmpirɨt͡ʂnɨ', 'Badania empiryczne.', 'Empirical research.', 'Эмпирические исследования.'),
('abstrakcyjny', 'abstract', 'абстрактный', 'adjective', 'masculine', 'C1', 1309, 'apstraktsjnɨ', 'Myślenie abstrakcyjne.', 'Abstract thinking.', 'Абстрактное мышление.'),
('synteza', 'synthesis', 'синтез', 'noun', 'feminine', 'C1', 1310, 'sɨntɛza', 'Synteza wyników badań.', 'Synthesis of research results.', 'Синтез результатов исследований.'),
('implikacja', 'implication', 'импликация', 'noun', 'feminine', 'C1', 1311, 'implikat͡sja', 'Jakie są implikacje?', 'What are the implications?', 'Каковы импликации?'),
('paradoks', 'paradox', 'парадокс', 'noun', 'masculine', 'C1', 1312, 'paradɔks', 'To interesujący paradoks.', 'This is an interesting paradox.', 'Это интересный парадокс.'),
('dogmat', 'dogma', 'догма', 'noun', 'masculine', 'C1', 1313, 'dɔgmat', 'Kwestionować dogmaty.', 'To question dogmas.', 'Подвергать сомнению догмы.'),
('aksjomatyczny', 'axiomatic', 'аксиоматический', 'adjective', 'masculine', 'C1', 1314, 'aksjɔmatɨt͡ʂnɨ', 'Prawda aksjomatyczna.', 'Axiomatic truth.', 'Аксиоматическая истина.'),
('dychotomia', 'dichotomy', 'дихотомия', 'noun', 'feminine', 'C1', 1315, 'dɨxɔtɔmʲa', 'Fałszywa dychotomia.', 'False dichotomy.', 'Ложная дихотомия.');
