('inkubator', 'incubator', 'инкубатор', 'noun', 'masculine', 'C1', 1327, 'inkubatɔr', 'Inkubator przedsiębiorczości.', 'Business incubator.', 'Инкубатор предпринимательства.'),
('startup', 'startup', 'стартап', 'noun', 'masculine', 'C1', 1328, 'startup', 'Założyłem startup.', 'I founded a startup.', 'Я основал стартап.'),
('unicorn', 'unicorn (billion-dollar startup)', 'единорог', 'noun', 'masculine', 'C1', 1329, 'junikɔrn', 'Firma stała się unicornem.', 'The company became a unicorn.', 'Компания стала единорогом.'),
('ekosystem', 'ecosystem', 'экосистема', 'noun', 'masculine', 'C1', 1330, 'ɛkɔsistɛm', 'Ekosystem startupowy.', 'Startup ecosystem.', 'Стартап-экосистема.');
